/**
 * Zeichnet einen Automaten als Zustandsübergangsdiagramm und zeigt, wie er ein Wort liest:
 * Der Lesekopf wandert über das Eingabeband, Pfeile und Zustände leuchten auf.
 * Erst den Automaten fertig bauen, dann das Bild erzeugen.
 * Muss nicht verändert werden.
 */
public class Automatenbild {
   private Automat automat;
   private int n;                   // Anzahl der Zustände
   private double[] x;              // Mittelpunkte der Zustände
   private double[] y;
   private Circle[] kreise;
   private Circle[] innen;          // innerer Kreis der Endzustände (sonst null)
   private Pfeil[][] pfeile;        // pfeile[von][nach], null = kein Pfeil
   private Rectangle[] felder;      // Eingabeband
   private Text[] zeichen;
   private Polygon lesekopf;
   private Text rzk;
   private Text meldung;
   private Pfeil leuchtend;         // zuletzt benutzter Pfeil
   private int aktuell;             // aktueller Zustand
   private boolean abgebrochen;
   private String wort = "";
   private int pause = 600;         // Millisekunden pro Schritt
   private double r = 24;           // Radius eines Zustands

   public Automatenbild(Automat automat) {
      World.clear();
      this.automat = automat;
      automat.setBild(this);
      n = automat.getAnzahlZustaende();
      x = new double[n];
      y = new double[n];
      double abstand = 150;
      if (n > 1) {
         abstand = Math.min(150, 620.0 / (n - 1));
      }
      for (int i = 0; i < n; i++) {
         x[i] = 400 - abstand * (n - 1) / 2 + i * abstand;
         y[i] = 300;
      }
      zeichnePfeile();
      zeichneZustaende();
      felder = new Rectangle[0];
      zeichen = new Text[0];
      meldung = new Text(400, 470, 24, "");
      rzk = new Text(40, 128, 20, "");
      rzk.setFillColor("#334155");
   }

   // Langsamer oder schneller abspielen (Millisekunden pro Schritt)
   public void setPause(int millisekunden) {
      pause = millisekunden;
   }

   // ---------- Diagramm zeichnen ----------

   private void zeichneZustaende() {
      kreise = new Circle[n];
      innen = new Circle[n];
      for (int i = 0; i < n; i++) {
         kreise[i] = new Circle(x[i], y[i], r);
         kreise[i].setBorderColor("#0369a1");
         kreise[i].setBorderWidth(2);
         if (automat.istEndzustand(i)) {
            innen[i] = new Circle(x[i], y[i], r - 6);
            innen[i].setBorderColor("#0369a1");
            innen[i].setBorderWidth(2);
         }
         Text name = new Text(x[i], y[i], 20, "Z" + i);
         name.setFillColor("#0c4a6e");
         zentriere(name, x[i], y[i]);
         faerbe(i, "#e0f2fe");
      }
      // Startpfeil an Z0
      Line start = new Line(x[0] - r - 46, y[0], x[0] - r - 2, y[0]);
      start.setBorderColor("#334155");
      start.setBorderWidth(2);
      double[] ecken = {x[0] - r, y[0], x[0] - r - 12, y[0] - 6, x[0] - r - 12, y[0] + 6};
      Polygon spitze = new Polygon(true, ecken);
      spitze.setFillColor("#334155");
      spitze.setBorderWidth(0);
      Text t = new Text(x[0] - r - 50, y[0] - 26, 16, "Start");
      t.setFillColor("#475569");
   }

   private void faerbe(int z, String farbe) {
      kreise[z].setFillColor(farbe);
      if (innen[z] != null) {
         innen[z].setFillColor(farbe);
      }
   }

   private void zeichnePfeile() {
      pfeile = new Pfeil[n][n];
      for (int von = 0; von < n; von++) {
         for (int nach = 0; nach < n; nach++) {
            String text = beschriftung(von, nach);
            if (!text.equals("")) {
               if (von == nach) {
                  pfeile[von][nach] = schleife(von, text);
               } else {
                  pfeile[von][nach] = bogen(von, nach, text);
               }
            }
         }
      }
      for (int von = 0; von < n; von++) {
         for (int nach = 0; nach < n; nach++) {
            if (pfeile[von][nach] != null) {
               pfeile[von][nach].beschriftungNachVorne();
            }
         }
      }
   }

   // Alle Zeichen, mit denen man von "von" nach "nach" kommt, z. B. "h" oder "1–9"
   private String beschriftung(int von, int nach) {
      String alphabet = automat.getAlphabet();
      String text = "";
      int s = 0;
      while (s < alphabet.length()) {
         if (automat.getEintrag(von, s) == nach) {
            int ende = s;
            while (ende + 1 < alphabet.length() && automat.getEintrag(von, ende + 1) == nach
                   && Character.isLetterOrDigit(alphabet.charAt(ende)) && Character.isLetterOrDigit(alphabet.charAt(ende + 1))) {
               ende++;
            }
            if (!text.equals("")) {
               text = text + ", ";
            }
            if (ende - s >= 2) {
               text = text + alphabet.charAt(s) + "–" + alphabet.charAt(ende);
            } else {
               for (int k = s; k <= ende; k++) {
                  if (k > s) {
                     text = text + ", ";
                  }
                  text = text + alphabet.charAt(k);
               }
            }
            s = ende + 1;
         } else {
            s++;
         }
      }
      return text;
   }

   // Pfeil zwischen zwei Zuständen: vorwärts oben herum, rückwärts unten herum
   private Pfeil bogen(int von, int nach, String text) {
      int weite = Math.abs(nach - von);
      boolean gegenrichtung = !beschriftung(nach, von).equals("");
      double hoehe = 0;
      if (weite == 1 && gegenrichtung) {
         hoehe = 22;
      } else if (weite > 1) {
         hoehe = Math.min(150, 65 + 25 * (weite - 1));   // über Zustände (und ihre Schleifen) hinweg
      }
      if (nach < von) {
         hoehe = -hoehe;
      }
      double kx = (x[von] + x[nach]) / 2;      // Kontrollpunkt der Kurve
      double ky = y[von] - 2 * hoehe;
      double[] a = randpunkt(von, kx, ky);
      double[] b = randpunkt(nach, kx, ky);
      int stuecke = 16;
      double[] punkte = new double[2 * (stuecke + 1)];
      for (int k = 0; k <= stuecke; k++) {
         double t = 1.0 * k / stuecke;
         punkte[2 * k] = (1 - t) * (1 - t) * a[0] + 2 * (1 - t) * t * kx + t * t * b[0];
         punkte[2 * k + 1] = (1 - t) * (1 - t) * a[1] + 2 * (1 - t) * t * ky + t * t * b[1];
      }
      double tx = punkte[stuecke];
      double ty = punkte[stuecke + 1] - 16;
      if (hoehe < 0) {
         ty = punkte[stuecke + 1] + 16;
      }
      return new Pfeil(punkte, text, tx, ty);
   }

   // Punkt auf dem Rand von Zustand z in Richtung (zx, zy)
   private double[] randpunkt(int z, double zx, double zy) {
      double dx = zx - x[z];
      double dy = zy - y[z];
      double l = Math.sqrt(dx * dx + dy * dy);
      double[] p = {x[z] + r * dx / l, y[z] + r * dy / l};
      return p;
   }

   // Schleife oben am Zustand
   private Pfeil schleife(int z, String text) {
      double mx = x[z];
      double my = y[z] - r - 12;
      int stuecke = 16;
      double[] punkte = new double[2 * (stuecke + 1)];
      for (int k = 0; k <= stuecke; k++) {
         double winkel = Math.toRadians(140 + 260.0 * k / stuecke);
         punkte[2 * k] = mx + 18 * Math.cos(winkel);
         punkte[2 * k + 1] = my + 18 * Math.sin(winkel);
      }
      return new Pfeil(punkte, text, mx, my - 32);
   }

   // ---------- Ablauf zeigen ----------

   // Eingabeband neu aufbauen, Lesekopf auf das erste Zeichen, Startzustand leuchtet
   public void zeigeStart(String wort) {
      this.wort = wort;
      for (int i = 0; i < felder.length; i++) {
         felder[i].destroy();
         zeichen[i].destroy();
      }
      if (lesekopf != null) {
         lesekopf.destroy();
      }
      if (leuchtend != null) {
         leuchtend.leuchten(false);
         leuchtend = null;
      }
      for (int z = 0; z < n; z++) {
         faerbe(z, "#e0f2fe");
      }
      felder = new Rectangle[wort.length()];
      zeichen = new Text[wort.length()];
      double breite = Math.min(40, 720.0 / Math.max(1, wort.length()));
      for (int i = 0; i < wort.length(); i++) {
         felder[i] = new Rectangle(40 + i * breite, 40, breite, 40);
         felder[i].setFillColor("#ffffff");
         felder[i].setBorderColor("#475569");
         felder[i].setBorderWidth(2);
         zeichen[i] = new Text(0, 0, 22, "" + wort.charAt(i));
         zeichen[i].setFillColor("#0f172a");
         zentriere(zeichen[i], 40 + i * breite + breite / 2, 60);
      }
      double[] ecken = {40 + breite / 2, 84, 40 + breite / 2 - 8, 98, 40 + breite / 2 + 8, 98};
      lesekopf = new Polygon(true, ecken);
      lesekopf.setFillColor("#0f172a");
      lesekopf.setBorderWidth(0);
      if (wort.length() == 0) {
         lesekopf.setVisible(false);
         zeichen = new Text[0];
      } else {
         felder[0].setFillColor("#fdba74");
      }
      aktuell = 0;
      abgebrochen = false;
      faerbe(0, "#fde047");
      zeigeRZK(0);
      meldung.setText("Eingabe: " + wort);
      if (wort.length() == 0) {
         meldung.setText("Eingabe: ε (leeres Wort)");
      }
      meldung.setFillColor("#334155");
      zentriere(meldung, 400, 470);
      SystemTools.pause(pause);
   }

   // Ein Schritt: Zeichen i wird gelesen, der Automat wechselt von alt nach neu (-1: kein Pfeil)
   public void zeigeSchritt(int alt, int neu, int i) {
      if (i < 0 || i >= wort.length()) {
         return;
      }
      if (leuchtend != null) {
         leuchtend.leuchten(false);
      }
      felder[i].setFillColor("#fdba74");
      setzeLesekopf(i);
      if (neu < 0 || neu >= n || pfeile[alt][neu] == null) {
         felder[i].setFillColor("#fecdd3");
         faerbe(alt, "#fecdd3");
         abgebrochen = true;
         meldung.setText("Abbruch: In Z" + alt + " gibt es keinen Pfeil für " + wort.charAt(i));
         meldung.setFillColor("#be123c");
         zentriere(meldung, 400, 470);
         SystemTools.pause(pause);
         return;
      }
      leuchtend = pfeile[alt][neu];
      leuchtend.leuchten(true);
      fahre(leuchtend.getPunkte());
      faerbe(alt, "#e0f2fe");
      faerbe(neu, "#fde047");
      aktuell = neu;
      felder[i].setFillColor("#e2e8f0");
      if (i + 1 < wort.length()) {
         felder[i + 1].setFillColor("#fdba74");
         setzeLesekopf(i + 1);
      } else {
         lesekopf.setVisible(false);
      }
      zeigeRZK(i + 1);
      SystemTools.pause(pause);
   }

   // Ergebnis anzeigen: akzeptiert oder abgelehnt
   public void zeigeErgebnis(boolean akzeptiert) {
      if (akzeptiert) {
         meldung.setText("akzeptiert: RZK leer und Z" + aktuell + " ist Endzustand");
         meldung.setFillColor("#15803d");
         faerbe(aktuell, "#86efac");
      } else if (abgebrochen) {
         meldung.setText(meldung.getText() + " – abgelehnt");
      } else {
         meldung.setText("abgelehnt: Z" + aktuell + " ist kein Endzustand");
         meldung.setFillColor("#be123c");
      }
      zentriere(meldung, 400, 470);
      SystemTools.pause(2 * pause);
   }

   // Text mittig auf (mx, my) setzen (moveTo setzt bei Texten die linke obere Ecke)
   private void zentriere(Text t, double mx, double my) {
      t.moveTo(mx - t.getWidth() / 2, my - t.getHeight() / 2);
   }

   // Lesekopf unter Feld i schieben
   private void setzeLesekopf(int i) {
      double breite = felder[i].getWidth();
      lesekopf.moveTo(40 + i * breite + breite / 2, 91);
   }

   private void zeigeRZK(int ab) {
      if (ab >= wort.length()) {
         rzk.setText("RZK: leer");
      } else {
         rzk.setText("RZK: " + wort.substring(ab));
      }
   }

   // Ein Punkt fährt den Pfeil entlang
   private void fahre(double[] punkte) {
      Circle punkt = new Circle(punkte[0], punkte[1], 8);
      punkt.setFillColor("#ea580c");
      punkt.setBorderColor("#ffffff");
      for (int k = 2; k < punkte.length; k = k + 2) {
         punkt.moveTo(punkte[k], punkte[k + 1]);
         SystemTools.pause(pause / 25);
      }
      punkt.destroy();
   }
}

/**
 * Ein Pfeil im Zustandsübergangsdiagramm: Linie (aus kurzen Stücken), Spitze und Beschriftung.
 * Muss nicht verändert werden.
 */
public class Pfeil {
   private Line[] striche;
   private Polygon spitze;
   private Text text;
   private Rectangle grund;     // weißer Hintergrund der Beschriftung
   private double[] punkte;     // x0, y0, x1, y1, … entlang des Pfeils

   public Pfeil(double[] punkte, String beschriftung, double textX, double textY) {
      this.punkte = punkte;
      int n = punkte.length;
      striche = new Line[n / 2 - 1];
      for (int k = 0; k < striche.length; k++) {
         striche[k] = new Line(punkte[2 * k], punkte[2 * k + 1], punkte[2 * k + 2], punkte[2 * k + 3]);
      }
      double ex = punkte[n - 2];
      double ey = punkte[n - 1];
      double dx = ex - punkte[n - 4];
      double dy = ey - punkte[n - 3];
      double laenge = Math.sqrt(dx * dx + dy * dy);
      dx = dx / laenge;
      dy = dy / laenge;
      double[] ecken = {ex, ey, ex - 13 * dx + 6 * dy, ey - 13 * dy - 6 * dx, ex - 13 * dx - 6 * dy, ey - 13 * dy + 6 * dx};
      spitze = new Polygon(true, ecken);
      spitze.setBorderWidth(0);
      text = new Text(textX, textY, 20, beschriftung);
      double b = text.getWidth() + 8;
      double h = text.getHeight();
      grund = new Rectangle(textX - b / 2, textY - h / 2, b, h);
      grund.setFillColor("#ffffff");
      grund.setBorderWidth(0);
      text.moveTo(textX - text.getWidth() / 2, textY - h / 2);
      text.bringToFront();
      leuchten(false);
   }

   // Pfeil hervorheben (an = true) oder normal zeichnen
   public void leuchten(boolean an) {
      String farbe = "#334155";
      double breite = 2;
      if (an) {
         farbe = "#ea580c";
         breite = 5;
      }
      for (int k = 0; k < striche.length; k++) {
         striche[k].setBorderColor(farbe);
         striche[k].setBorderWidth(breite);
      }
      spitze.setFillColor(farbe);
      if (an) {
         text.setFillColor("#c2410c");
      } else {
         text.setFillColor("#0f172a");
      }
   }

   // Beschriftung über alle Linien legen
   public void beschriftungNachVorne() {
      grund.bringToFront();
      text.bringToFront();
   }

   public double[] getPunkte() {
      return punkte;
   }
}

/**
