 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class AutomatTest {

   // der Lach-Automat aus Aufgabe 1, ohne Bild
   private Automat lachen() {
      Automat a = new Automat(3, "ha");
      a.uebergangHinzufuegen(0, 'h', 1);
      a.uebergangHinzufuegen(1, 'a', 2);
      a.uebergangHinzufuegen(2, 'h', 1);
      a.setEndzustand(2);
      return a;
   }

   @Test
   public void tabelleAnfangsLeer() {
      Automat a = new Automat(3, "ha");
      for (int z = 0; z < 3; z++) {
         for (int s = 0; s < 2; s++) {
            Assertions.assertEquals(-1, a.getEintrag(z, s), "TODO 1: In einem neuen Automaten muss jedes Feld der Tabelle -1 sein (Zeile " + z + ", Spalte " + s + ").");
         }
      }
   }

   @Test
   public void endzustandSetzen() {
      Automat a = new Automat(3, "ha");
      a.setEndzustand(2);
      Assertions.assertTrue(a.istEndzustand(2), "TODO 1: Nach setEndzustand(2) muss Z2 ein Endzustand sein.");
      Assertions.assertFalse(a.istEndzustand(0), "TODO 1: Z0 ist kein Endzustand.");
   }

   @Test
   public void uebergangEintragen() {
      Automat a = lachen();
